<?php
require_once 'includes.php';
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $action=$_POST['action']??''; $id=(int)($_POST['product_id']??0); $qty=max(1,(int)($_POST['quantity']??1));
  if($action==='add') { $p=get_product($pdo,$id); if(!$p){flash('error','Product not found.');} elseif($p['stock']<1){flash('error','This product is out of stock.');} else { $current=$_SESSION['cart'][$id]??0; $_SESSION['cart'][$id]=min($p['stock'],$current+$qty); flash('success',$p['name'].' added to cart.'); } header('Location: cart.php'); exit; }
  if($action==='update'){ foreach(($_POST['qty']??[]) as $pid=>$q){$pid=(int)$pid;$q=(int)$q;$p=get_product($pdo,$pid);if($p && $q>0)$_SESSION['cart'][$pid]=min($p['stock'],$q);else unset($_SESSION['cart'][$pid]);} header('Location: cart.php');exit; }
  if($action==='remove'){unset($_SESSION['cart'][$id]);header('Location: cart.php');exit;}
  if($action==='clear'){$_SESSION['cart']=[];header('Location: cart.php');exit;}
}
$items=[];$total=0;foreach($_SESSION['cart']??[] as $id=>$qty){$p=get_product($pdo,(int)$id);if($p){$sub=$p['price']*$qty;$total+=$sub;$items[]=['p'=>$p,'qty'=>$qty,'sub'=>$sub];}else unset($_SESSION['cart'][$id]);}
$flash=get_flash(); $page_title='R5 Essence | Cart & Checkout'; require 'header.php'; ?>
<main><section class="section products-section"><div class="offer-heading"><p class="section-label">YOUR ORDER</p><h2>Shopping <span>Cart</span></h2></div>
<?php if($flash): ?><div class="site-flash <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<div class="cart-page-wrap"><div class="cart-page-top"><div><p class="section-label">YOUR ITEMS</p><h3 class="cart-page-title">Selected <span>Products</span></h3></div><?php if($items): ?><form method="post"><input type="hidden" name="action" value="clear"><button class="clear-cart-btn">Clear Cart</button></form><?php endif; ?></div>
<?php if(!$items): ?><div class="empty-cart"><div class="empty-cart-icon">🛒</div><strong>Your cart is empty.</strong><p>Add a product from our collection to continue.</p><a href="products.php">Browse Products</a></div><?php else: ?><div class="checkout-layout cart-checkout-layout"><div><form method="post"><input type="hidden" name="action" value="update"><div class="cart-items"><?php foreach($items as $i): $p=$i['p']; ?><div class="cart-item"><img src="assets/<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><div class="cart-item-info"><h4><?= e($p['name']) ?></h4><p><?= money($p['price']) ?> each</p><div class="qty"><input style="width:70px" type="number" min="1" max="<?= (int)$p['stock'] ?>" name="qty[<?= (int)$p['product_id'] ?>]" value="<?= (int)$i['qty'] ?>"></div></div><div class="cart-item-right"><strong><?= money($i['sub']) ?></strong><button type="submit" formaction="cart.php" formmethod="post" name="action" value="remove" class="remove-item-btn">Remove</button><input type="hidden" name="product_id" value="<?= (int)$p['product_id'] ?>"></div></div><?php endforeach; ?></div><button class="gold-btn" type="submit" style="margin-top:15px">Update Cart</button></form><div class="cart-summary"><div><span>Subtotal</span><strong><?= money($total) ?></strong></div></div></div>
<form id="checkoutForm" method="post" action="checkout.php"><label>Full Name<input required name="name" placeholder="Enter your full name"></label><label>Contact Number<input required name="phone" placeholder="09XX XXX XXXX"></label><label>Complete Address<textarea required name="address" rows="4" placeholder="House/Street, Barangay, Municipality, Province"></textarea></label><label>Order Notes <span class="optional">(optional)</span><textarea name="notes" rows="2"></textarea></label><div class="payment-note"><strong>Payment:</strong> Demo checkout. Payment gateway can be connected later.</div><div class="form-actions"><button class="gold-btn solid" type="submit">Place Order</button><button class="clear-form-btn" type="reset">Clear Form</button></div></form></div><?php endif; ?></div></section></main>
<?php require 'footer.php'; ?>
